-- E-conomic v1.6 frontend OTA — presupuestos, metas, flujo de caja y notificaciones.
do $migration$
declare v_html text;v_new text;v_addon text;v_sha text;
begin
if exists(select 1 from public.app_releases where version_code=9 and version='1.6.0') then return; end if;
select html into v_html from public.app_releases where is_active order by version_code desc,id desc limit 1;
if v_html is null then raise exception 'No active frontend release found'; end if;
if strpos(v_html,'id="v16Script"')>0 then raise exception 'v1.6 frontend already present in source release'; end if;
v_addon := $v16$
<style id="v16Style">
.v16-top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}.v16-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:14px 0}.v16-kpi{background:var(--card2);border:1px solid var(--border);border-radius:12px;padding:12px}.v16-kpi span{display:block;font-size:9px;text-transform:uppercase;font-weight:900;color:var(--muted)}.v16-kpi strong{display:block;font-size:18px;margin-top:5px}.v16-kpi small{display:block;font-size:9px;color:var(--muted);margin-top:3px}.v16-headrow{display:flex;justify-content:space-between;align-items:end;gap:10px;margin:18px 0 9px}.v16-headrow h3{font-size:13px;margin:0 0 3px}.v16-budget-grid,.v16-goal-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.v16-budget,.v16-goal{background:var(--card2);border:1px solid var(--border);border-radius:12px;padding:11px}.v16-row{display:flex;justify-content:space-between;align-items:center;gap:10px}.v16-row strong{font-size:11px}.v16-row small{display:block;font-size:9px;color:var(--muted);margin-top:2px}.v16-progress{height:8px;background:var(--border);border-radius:999px;overflow:hidden;margin:9px 0}.v16-progress>div{height:100%;background:var(--primary);border-radius:999px}.v16-progress>div.green{background:var(--green)}.v16-progress>div.warn{background:var(--orange)}.v16-progress>div.red{background:var(--red)}.v16-pill{font-size:9px;font-weight:900;border:1px solid var(--border);border-radius:999px;padding:4px 7px;background:var(--card)}.v16-pill.ok{color:var(--green)}.v16-pill.bad{color:var(--red)}.v16-cash-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.v16-cash{background:var(--card2);border:1px solid var(--border);border-radius:12px;padding:12px}.v16-cash span{display:block;font-size:9px;font-weight:900;color:var(--muted)}.v16-cash strong{display:block;font-size:16px;margin:5px 0}.v16-cash small{font-size:9px;line-height:1.45;color:var(--muted)}.v16-alert-list{display:grid;gap:7px}.v16-alert{display:grid;grid-template-columns:30px 1fr;gap:9px;align-items:center;border:1px solid var(--border);border-radius:11px;background:var(--card2);padding:9px 11px}.v16-alert.level2{border-color:color-mix(in srgb,var(--orange) 35%,var(--border));background:color-mix(in srgb,var(--orange) 7%,var(--card))}.v16-alert.level3{border-color:color-mix(in srgb,var(--red) 40%,var(--border));background:color-mix(in srgb,var(--red) 8%,var(--card))}.v16-alert.ok{border-color:color-mix(in srgb,var(--green) 30%,var(--border));background:color-mix(in srgb,var(--green) 7%,var(--card))}.v16-alert strong{display:block;font-size:10px}.v16-alert small{display:block;color:var(--muted);font-size:9px;margin-top:2px}.v16-modal{position:fixed;inset:0;z-index:155;background:rgba(0,0,0,.68);display:flex;align-items:center;justify-content:center;padding:18px}.v16-modal-card{width:min(560px,100%);max-height:92vh;overflow:auto;background:var(--card);border:1px solid var(--border);border-radius:18px;padding:18px;box-shadow:0 25px 80px rgba(0,0,0,.35)}.v16-modal-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;margin-bottom:14px}.v16-modal-head h2{margin:0}@media(max-width:850px){.v16-kpis{grid-template-columns:1fr 1fr}.v16-budget-grid,.v16-goal-grid{grid-template-columns:1fr}.v16-cash-grid{grid-template-columns:1fr 1fr 1fr}}@media(max-width:600px){.v16-kpis,.v16-cash-grid{grid-template-columns:1fr 1fr}.v16-headrow{align-items:stretch;flex-direction:column}.v16-headrow .actions{width:100%}.v16-headrow .actions input{flex:1}.v16-modal{padding:7px}.v16-modal-card{padding:14px;border-radius:14px}}@media(max-width:420px){.v16-kpis,.v16-cash-grid{grid-template-columns:1fr}}
</style>
<script id="v16Script">
(function(){
let v16Budgets=[],v16Goals=[],v16Obligations=[],v16Payments=[],v16Channel=null,v16Ready=false,v16BudgetEditId=null,v16GoalEditId=null;
const V16_NOTIFY_ENABLED='finance_v16_notify_enabled_v1',V16_NOTIFY_SEEN='finance_v16_notify_seen_v1',V16_SCHEDULED='finance_v16_scheduled_v1';
const v16Pad=n=>String(n).padStart(2,'0');
function v16Today(d=new Date()){return d.getFullYear()+'-'+v16Pad(d.getMonth()+1)+'-'+v16Pad(d.getDate())}
function v16MonthKey(d=new Date()){return d.getFullYear()+'-'+v16Pad(d.getMonth()+1)}
function v16Date(s){const p=String(s||'').split('-').map(Number);return p.length===3&&p[0]?new Date(p[0],p[1]-1,p[2]):new Date()}
function v16MonthStart(key){return /^\d{4}-\d{2}$/.test(key||'')?key+'-01':v16MonthKey()+'-01'}
function v16MonthEnd(key){const p=String(key||'').split('-').map(Number),d=new Date(p[0],p[1],0);return v16Today(d)}
function v16DaysTo(s){const a=v16Date(v16Today()),b=v16Date(s);return Math.round((b-a)/86400000)}
function v16Num(v){return Number(v)||0}
function v16Posted(id){return v16Payments.filter(p=>p.obligation_id===id&&p.status==='posted')}
function v16Paid(o){return v16Posted(o.id).reduce((s,p)=>s+v16Num(p.applied_original),0)}
function v16Remaining(o){return Math.max(0,v16Num(o.amount_original)-v16Paid(o))}
function v16RemainingUsd(o){const total=v16Num(o.amount_original),rem=v16Remaining(o);return total>0?v16Num(o.usd_bcv)*(rem/total):0}
function v16ActiveOb(o){return o.status!=='paid'&&o.status!=='cancelled'&&v16Remaining(o)>.000001}
function v16Owner(){return membership?.role==='owner'}
function v16TxBetween(start,end){return (transactions||[]).filter(t=>(t.occurred_on||'')>=start&&(t.occurred_on||'')<=end)}
function v16BudgetSpend(b){const key=String(b.period_start||'').slice(0,7),rows=v16TxBetween(v16MonthStart(key),v16MonthEnd(key)).filter(t=>t.type==='expense'&&(b.category==='*'||t.category===b.category));return rows.reduce((s,t)=>s+v16Num(t.usd_bcv),0)}
function v16BudgetState(b){const spent=v16BudgetSpend(b),limit=v16Num(b.limit_usd),pct=limit>0?(spent/limit)*100:0;return{spent,limit,pct,over:pct>=100,warn:pct>=v16Num(b.alert_percent)}}
function v16GoalValue(g){const end=(g.end_date||v16Today())<v16Today()?g.end_date:v16Today();if(g.goal_type==='balance'){return (transactions||[]).filter(t=>(t.occurred_on||'')<=end).reduce((s,t)=>s+(t.type==='income'?1:-1)*v16Num(t.usd_bcv),0)}const rows=v16TxBetween(g.start_date,end),income=rows.filter(t=>t.type==='income').reduce((s,t)=>s+v16Num(t.usd_bcv),0),expense=rows.filter(t=>t.type==='expense').reduce((s,t)=>s+v16Num(t.usd_bcv),0);return g.goal_type==='net'?income-expense:income}
function v16GoalState(g){const value=v16GoalValue(g),target=v16Num(g.target_usd),pct=target>0?Math.max(0,value/target*100):0,days=v16DaysTo(g.end_date);return{value,target,pct,achieved:value>=target,expired:days<0,days}}
function v16CurrentBalance(){return (transactions||[]).reduce((s,t)=>s+(t.type==='income'?1:-1)*v16Num(t.usd_bcv),0)}
function v16Projection(days){const cutoff=new Date();cutoff.setDate(cutoff.getDate()+days);const end=v16Today(cutoff);let incoming=0,outgoing=0;v16Obligations.filter(v16ActiveOb).filter(o=>(o.due_date||'')<=end).forEach(o=>{const rem=v16RemainingUsd(o);if(o.kind==='receivable')incoming+=rem;else outgoing+=rem});return{days,incoming,outgoing,balance:v16CurrentBalance()+incoming-outgoing}}
function v16GoalTypeLabel(t){return t==='net'?'Resultado neto':t==='balance'?'Saldo de caja':'Ingresos'}
function v16BudgetLabel(b){return b.category==='*'?'Presupuesto total':b.category}
function v16MonthLabel(key){const p=String(key||'').split('-').map(Number);return p[0]&&p[1]?new Date(p[0],p[1]-1,1).toLocaleDateString('es-VE',{month:'long',year:'numeric'}):key}
function v16Build(){if(v16Ready||$('v16Planning'))return;const anchor=$('v15Accounts')||$('v14Reports')||document.querySelector('#appScreen .grid');if(!anchor)return;const card=document.createElement('section');card.id='v16Planning';card.className='card';card.innerHTML=`<div class="v16-top"><div><h2 style="margin:0">Planificación financiera</h2><div class="muted">Presupuestos, metas, flujo de caja proyectado y notificaciones</div></div><button id="v16Notify" class="btn btn-secondary" type="button">🔔 Notificaciones</button></div><div class="v16-kpis"><div class="v16-kpi"><span>Presupuesto usado</span><strong id="v16BudgetKpi">—</strong><small id="v16BudgetKpiSub">Sin presupuesto</small></div><div class="v16-kpi"><span>Metas activas</span><strong id="v16GoalsKpi">0</strong><small id="v16GoalsKpiSub">0 alcanzadas</small></div><div class="v16-kpi"><span>Caja proyectada 30d</span><strong id="v16CashKpi">$0.00</strong><small id="v16CashKpiSub"></small></div><div class="v16-kpi"><span>Alertas</span><strong id="v16AlertsKpi">0</strong><small id="v16AlertsKpiSub">Todo al día</small></div></div><div class="v16-headrow"><div><h3>Presupuestos mensuales</h3><div class="muted">Controla el gasto total o por categoría</div></div><div class="actions"><input id="v16Month" type="month" style="width:165px"><button id="v16NewBudget" class="btn btn-primary" type="button">+ Presupuesto</button></div></div><div id="v16Budgets" class="v16-budget-grid"></div><div class="v16-headrow"><div><h3>Metas financieras</h3><div class="muted">Ingresos, resultado neto o saldo objetivo</div></div><button id="v16NewGoal" class="btn btn-primary" type="button">+ Meta</button></div><div id="v16Goals" class="v16-goal-grid"></div><div class="v16-headrow"><div><h3>Flujo de caja proyectado</h3><div class="muted">Saldo actual + cuentas por cobrar − cuentas por pagar según vencimientos</div></div></div><div id="v16Cashflow" class="v16-cash-grid"></div><div class="v16-headrow"><div><h3>Alertas inteligentes</h3><div class="muted">Vencimientos, presupuestos y metas</div></div></div><div id="v16Alerts" class="v16-alert-list"></div>`;anchor.parentNode.insertBefore(card,anchor);const bmodal=document.createElement('div');bmodal.id='v16BudgetModal';bmodal.className='v16-modal hidden';bmodal.innerHTML=`<div class="v16-modal-card"><div class="v16-modal-head"><div><h2 id="v16BudgetTitle">Presupuesto</h2><div class="muted">El Owner administra los límites del negocio.</div></div><button id="v16BudgetClose" class="icon-btn" type="button">×</button></div><form id="v16BudgetForm"><div class="form-group"><label>Categoría</label><select id="v16BudgetCategory"></select></div><div class="form-row"><div class="form-group"><label>Límite mensual USD</label><input id="v16BudgetLimit" type="number" min="0.01" step="0.01" required></div><div class="form-group"><label>Alertar al</label><select id="v16BudgetAlert"><option value="70">70%</option><option value="80" selected>80%</option><option value="90">90%</option><option value="100">100%</option></select></div></div><div class="actions"><button class="btn btn-primary" type="submit">Guardar</button><button id="v16BudgetDelete" class="btn btn-danger hidden" type="button">Eliminar</button></div></form></div>`;document.body.appendChild(bmodal);const gmodal=document.createElement('div');gmodal.id='v16GoalModal';gmodal.className='v16-modal hidden';gmodal.innerHTML=`<div class="v16-modal-card"><div class="v16-modal-head"><div><h2 id="v16GoalTitle">Meta financiera</h2><div class="muted">Define un objetivo medible en USD.</div></div><button id="v16GoalClose" class="icon-btn" type="button">×</button></div><form id="v16GoalForm"><div class="form-group"><label>Nombre de la meta</label><input id="v16GoalName" maxlength="160" required placeholder="Ej.: Facturar $10.000 este mes"></div><div class="form-row"><div class="form-group"><label>Tipo</label><select id="v16GoalType"><option value="income">Ingresos objetivo</option><option value="net">Resultado neto objetivo</option><option value="balance">Saldo de caja objetivo</option></select></div><div class="form-group"><label>Objetivo USD</label><input id="v16GoalTarget" type="number" min="0.01" step="0.01" required></div></div><div class="form-row"><div class="form-group"><label>Desde</label><input id="v16GoalStart" type="date" required></div><div class="form-group"><label>Hasta</label><input id="v16GoalEnd" type="date" required></div></div><div class="actions"><button class="btn btn-primary" type="submit">Guardar</button><button id="v16GoalArchive" class="btn btn-danger hidden" type="button">Archivar</button></div></form></div>`;document.body.appendChild(gmodal);$('v16Month').value=$('v14Month')?.value||$('v12Month')?.value||v16MonthKey();$('v16Month').addEventListener('input',v16Render);$('v16NewBudget').onclick=()=>v16OpenBudget();$('v16NewGoal').onclick=()=>v16OpenGoal();$('v16Notify').onclick=v16ToggleNotifications;$('v16BudgetClose').onclick=v16CloseBudget;$('v16GoalClose').onclick=v16CloseGoal;bmodal.addEventListener('click',e=>{if(e.target===bmodal)v16CloseBudget()});gmodal.addEventListener('click',e=>{if(e.target===gmodal)v16CloseGoal()});$('v16BudgetForm').onsubmit=v16SaveBudget;$('v16BudgetDelete').onclick=v16DeleteBudget;$('v16GoalForm').onsubmit=v16SaveGoal;$('v16GoalArchive').onclick=v16ArchiveGoal;$('v14Month')?.addEventListener('input',e=>{if($('v16Month')){$('v16Month').value=e.target.value;v16Render()}});$('v12Month')?.addEventListener('input',e=>{if($('v16Month')){$('v16Month').value=e.target.value;v16Render()}});v16Ready=true}
async function v16Load(){if(!sb||!business)return;const[b,g,o,p]=await Promise.all([sb.from('monthly_budgets').select('*').eq('business_id',business.id).order('period_start',{ascending:false}).order('category'),sb.from('financial_goals').select('*').eq('business_id',business.id).order('end_date',{ascending:true}),sb.from('obligations').select('*').eq('business_id',business.id).order('due_date',{ascending:true}),sb.from('obligation_payments').select('*').eq('business_id',business.id).order('paid_on',{ascending:false})]);if(b.error){console.warn('v16 budgets',b.error);return}if(g.error){console.warn('v16 goals',g.error);return}v16Budgets=b.data||[];v16Goals=g.data||[];v16Obligations=o.error?[]:(o.data||[]);v16Payments=p.error?[]:(p.data||[]);v16Render();v16SyncNativeNotifications()}
function v16Subscribe(){if(v16Channel&&sb){sb.removeChannel(v16Channel);v16Channel=null}if(!sb||!business)return;v16Channel=sb.channel('planning-'+business.id).on('postgres_changes',{event:'*',schema:'public',table:'monthly_budgets',filter:`business_id=eq.${business.id}`},v16Load).on('postgres_changes',{event:'*',schema:'public',table:'financial_goals',filter:`business_id=eq.${business.id}`},v16Load).on('postgres_changes',{event:'*',schema:'public',table:'obligations',filter:`business_id=eq.${business.id}`},v16Load).on('postgres_changes',{event:'*',schema:'public',table:'obligation_payments',filter:`business_id=eq.${business.id}`},v16Load).subscribe()}
function v16AlertData(){const out=[];v16Obligations.filter(v16ActiveOb).forEach(o=>{const d=v16DaysTo(o.due_date);if(d<=v16Num(o.alert_days)){out.push({level:d<0?3:d===0?2:1,icon:o.kind==='receivable'?'📥':'📤',title:d<0?`${o.counterparty} · vencida`:d===0?`${o.counterparty} · vence hoy`:`${o.counterparty} · vence en ${d} días`,meta:`${o.kind==='receivable'?'Cobrar':'Pagar'} ${moneyUSD(v16RemainingUsd(o))} · ${formatDate(o.due_date)}`})}});const current=v16MonthKey();v16Budgets.filter(b=>String(b.period_start).slice(0,7)===current).forEach(b=>{const s=v16BudgetState(b);if(s.warn)out.push({level:s.over?3:2,icon:'📊',title:`${v16BudgetLabel(b)} · ${s.pct.toFixed(0)}% usado`,meta:`Gastado ${moneyUSD(s.spent)} de ${moneyUSD(s.limit)}`})});v16Goals.filter(g=>g.status==='active').forEach(g=>{const s=v16GoalState(g);if(s.achieved)out.push({level:1,icon:'🎯',title:`Meta alcanzada · ${g.name}`,meta:`${moneyUSD(s.value)} de ${moneyUSD(s.target)}`});else if(s.days>=0&&s.days<=7&&s.pct<80)out.push({level:2,icon:'⏳',title:`Meta próxima a vencer · ${g.name}`,meta:`${s.pct.toFixed(0)}% · faltan ${s.days} días`})});return out.sort((a,b)=>b.level-a.level)}
function v16Render(){v16Build();if(!v16Ready)return;const key=$('v16Month')?.value||v16MonthKey(),monthBudgets=v16Budgets.filter(b=>String(b.period_start).slice(0,7)===key),totalBudget=monthBudgets.find(b=>b.category==='*'),categoryBudgets=monthBudgets.filter(b=>b.category!=='*');let limit=0,spent=0;if(totalBudget){const s=v16BudgetState(totalBudget);limit=s.limit;spent=s.spent}else if(categoryBudgets.length){limit=categoryBudgets.reduce((n,b)=>n+v16Num(b.limit_usd),0);const cats=new Set(categoryBudgets.map(b=>b.category));spent=v16TxBetween(v16MonthStart(key),v16MonthEnd(key)).filter(t=>t.type==='expense'&&cats.has(t.category)).reduce((n,t)=>n+v16Num(t.usd_bcv),0)}const pct=limit>0?spent/limit*100:0;$('v16BudgetKpi').textContent=limit>0?pct.toFixed(0)+'%':'—';$('v16BudgetKpi').className=pct>=100?'red':pct>=80?'':'green';$('v16BudgetKpiSub').textContent=limit>0?`${moneyUSD(spent)} de ${moneyUSD(limit)}`:'Sin presupuesto';const activeGoals=v16Goals.filter(g=>g.status==='active'),achieved=activeGoals.filter(g=>v16GoalState(g).achieved).length;$('v16GoalsKpi').textContent=String(activeGoals.length);$('v16GoalsKpiSub').textContent=`${achieved} alcanzada${achieved===1?'':'s'}`;const p30=v16Projection(30);$('v16CashKpi').textContent=moneyUSD(p30.balance);$('v16CashKpi').className=p30.balance>=0?'green':'red';$('v16CashKpiSub').textContent=`+${moneyUSD(p30.incoming)} · -${moneyUSD(p30.outgoing)}`;const alerts=v16AlertData();$('v16AlertsKpi').textContent=String(alerts.length);$('v16AlertsKpiSub').textContent=alerts.length?'Requieren atención':'Todo al día';$('v16NewBudget').classList.toggle('hidden',!v16Owner());$('v16NewGoal').classList.toggle('hidden',!v16Owner());$('v16Budgets').innerHTML=monthBudgets.length?monthBudgets.map(b=>{const s=v16BudgetState(b),w=Math.min(100,s.pct),cls=s.over?'red':s.warn?'warn':'green';return`<div class="v16-budget"><div class="v16-row"><div><strong>${esc(v16BudgetLabel(b))}</strong><small>${v16MonthLabel(key)} · alerta ${b.alert_percent}%</small></div>${v16Owner()?`<button class="btn btn-link" type="button" onclick="v16OpenBudget('${b.id}')">Editar</button>`:''}</div><div class="v16-progress"><div class="${cls}" style="width:${w}%"></div></div><div class="v16-row"><small>${moneyUSD(s.spent)} gastados</small><strong>${moneyUSD(s.limit)}</strong></div></div>`}).join(''):'<div class="empty">No hay presupuestos definidos para este mes.</div>';$('v16Goals').innerHTML=activeGoals.length?activeGoals.map(g=>{const s=v16GoalState(g),w=Math.min(100,s.pct),status=s.achieved?'Alcanzada':s.expired?'Vencida':`${s.days} días`;return`<div class="v16-goal"><div class="v16-row"><div><strong>${esc(g.name)}</strong><small>${v16GoalTypeLabel(g.goal_type)} · hasta ${formatDate(g.end_date)}</small></div><span class="v16-pill ${s.achieved?'ok':s.expired?'bad':''}">${status}</span></div><div class="v16-progress"><div class="${s.achieved?'green':''}" style="width:${w}%"></div></div><div class="v16-row"><small>${moneyUSD(s.value)} · ${s.pct.toFixed(0)}%</small><div class="actions"><strong>${moneyUSD(s.target)}</strong>${v16Owner()?`<button class="btn btn-link" type="button" onclick="v16OpenGoal('${g.id}')">Editar</button>`:''}</div></div></div>`}).join(''):'<div class="empty">No hay metas activas.</div>';$('v16Cashflow').innerHTML=[7,15,30].map(d=>{const p=v16Projection(d);return`<div class="v16-cash"><span>EN ${d} DÍAS</span><strong class="${p.balance>=0?'green':'red'}">${moneyUSD(p.balance)}</strong><small>Saldo actual ${moneyUSD(v16CurrentBalance())}<br>+ cobros ${moneyUSD(p.incoming)} · − pagos ${moneyUSD(p.outgoing)}</small></div>`}).join('');$('v16Alerts').innerHTML=alerts.length?alerts.slice(0,10).map(a=>`<div class="v16-alert level${a.level}"><div>${a.icon}</div><div><strong>${esc(a.title)}</strong><small>${esc(a.meta)}</small></div></div>`).join(''):'<div class="v16-alert ok"><div>✓</div><div><strong>Sin alertas importantes</strong><small>Presupuestos, metas y vencimientos están bajo control.</small></div></div>';v16RenderNotifyButton()}
window.v16OpenBudget=function(id){if(!v16Owner()){toast('Solo el propietario puede administrar presupuestos');return}v16BudgetEditId=id||null;const b=id?v16Budgets.find(x=>x.id===id):null,sel=$('v16BudgetCategory');sel.innerHTML='<option value="*">Presupuesto total</option>'+(categories||[]).map(c=>`<option value="${esc(c.name)}">${esc(c.name)}</option>`).join('');sel.value=b?.category||'*';sel.disabled=!!b;$('v16BudgetTitle').textContent=b?'Editar presupuesto':'Nuevo presupuesto';$('v16BudgetLimit').value=b?.limit_usd||'';$('v16BudgetAlert').value=String(b?.alert_percent||80);$('v16BudgetDelete').classList.toggle('hidden',!b);$('v16BudgetModal').classList.remove('hidden')};function v16CloseBudget(){$('v16BudgetModal')?.classList.add('hidden');v16BudgetEditId=null}
async function v16SaveBudget(e){e.preventDefault();if(!v16Owner())return;const payload={business_id:business.id,period_start:v16MonthStart($('v16Month').value),category:$('v16BudgetCategory').value,limit_usd:Number($('v16BudgetLimit').value),alert_percent:Number($('v16BudgetAlert').value),updated_by:user.id};if(!(payload.limit_usd>0)){toast('Introduce un presupuesto válido');return}let error;if(v16BudgetEditId){({error}=await sb.from('monthly_budgets').update(payload).eq('id',v16BudgetEditId))}else{payload.created_by=user.id;({error}=await sb.from('monthly_budgets').insert(payload))}if(error){toast(error.message);return}v16CloseBudget();await v16Load();await loadActivity();toast('Presupuesto guardado')}
async function v16DeleteBudget(){if(!v16BudgetEditId||!v16Owner())return;if(!confirm('¿Eliminar este presupuesto?'))return;const{error}=await sb.from('monthly_budgets').delete().eq('id',v16BudgetEditId);if(error){toast(error.message);return}v16CloseBudget();await v16Load();await loadActivity();toast('Presupuesto eliminado')}
window.v16OpenGoal=function(id){if(!v16Owner()){toast('Solo el propietario puede administrar metas');return}v16GoalEditId=id||null;const g=id?v16Goals.find(x=>x.id===id):null,key=$('v16Month')?.value||v16MonthKey();$('v16GoalTitle').textContent=g?'Editar meta':'Nueva meta';$('v16GoalName').value=g?.name||'';$('v16GoalType').value=g?.goal_type||'income';$('v16GoalTarget').value=g?.target_usd||'';$('v16GoalStart').value=g?.start_date||v16MonthStart(key);$('v16GoalEnd').value=g?.end_date||v16MonthEnd(key);$('v16GoalArchive').classList.toggle('hidden',!g);$('v16GoalModal').classList.remove('hidden')};function v16CloseGoal(){$('v16GoalModal')?.classList.add('hidden');v16GoalEditId=null}
async function v16SaveGoal(e){e.preventDefault();if(!v16Owner())return;const payload={business_id:business.id,name:$('v16GoalName').value.trim(),goal_type:$('v16GoalType').value,target_usd:Number($('v16GoalTarget').value),start_date:$('v16GoalStart').value,end_date:$('v16GoalEnd').value,status:'active',updated_by:user.id};if(!payload.name||!(payload.target_usd>0)||payload.start_date>payload.end_date){toast('Revisa los datos de la meta');return}let error;if(v16GoalEditId){({error}=await sb.from('financial_goals').update(payload).eq('id',v16GoalEditId))}else{payload.created_by=user.id;({error}=await sb.from('financial_goals').insert(payload))}if(error){toast(error.message);return}v16CloseGoal();await v16Load();await loadActivity();toast('Meta guardada')}
async function v16ArchiveGoal(){if(!v16GoalEditId||!v16Owner())return;if(!confirm('¿Archivar esta meta?'))return;const{error}=await sb.from('financial_goals').update({status:'archived',updated_by:user.id}).eq('id',v16GoalEditId);if(error){toast(error.message);return}v16CloseGoal();await v16Load();await loadActivity();toast('Meta archivada')}
function v16Native(){return !!window.EconNotify&&typeof window.EconNotify.schedule==='function'}
function v16Enabled(){return localStorage.getItem(V16_NOTIFY_ENABLED)==='1'}
function v16HasPermission(){try{return v16Native()&&!!window.EconNotify.hasPermission()}catch(e){return false}}
function v16RenderNotifyButton(){const b=$('v16Notify');if(!b)return;if(!v16Native()){b.textContent='🔕 Instala Android 1.6 para notificaciones';b.className='btn btn-secondary';return}if(!v16Enabled()){b.textContent='🔔 Activar notificaciones';b.className='btn btn-secondary';return}if(!v16HasPermission()){b.textContent='⚠ Dar permiso de notificaciones';b.className='btn btn-secondary';return}b.textContent='🔔 Notificaciones activas';b.className='btn btn-primary'}
function v16ToggleNotifications(){if(!v16Native()){toast('Actualiza E-conomic a Android 1.6.0 para usar notificaciones');return}if(v16Enabled()&&v16HasPermission()){localStorage.setItem(V16_NOTIFY_ENABLED,'0');v16CancelKnownSchedules();toast('Notificaciones desactivadas');v16RenderNotifyButton();return}localStorage.setItem(V16_NOTIFY_ENABLED,'1');try{window.EconNotify.requestPermission()}catch(e){}toast('Activa el permiso cuando Android lo solicite');setTimeout(()=>{v16RenderNotifyButton();v16SyncNativeNotifications()},1200)}
function v16ScheduleAt(dateStr,hour=9){const p=String(dateStr||'').split('-').map(Number);return p.length===3?new Date(p[0],p[1]-1,p[2],hour,0,0,0).getTime():0}
function v16Shift(dateStr,days){const d=v16Date(dateStr);d.setDate(d.getDate()+days);return v16Today(d)}
function v16Seen(){try{return JSON.parse(localStorage.getItem(V16_NOTIFY_SEEN)||'{}')}catch{return{}}}
function v16ShowOnce(key,title,body){if(!v16Enabled()||!v16HasPermission())return;const seen=v16Seen();if(seen[key])return;try{window.EconNotify.showNow(key,title,body);seen[key]=Date.now();localStorage.setItem(V16_NOTIFY_SEEN,JSON.stringify(seen))}catch(e){}}
function v16KnownSchedules(){try{return JSON.parse(localStorage.getItem(V16_SCHEDULED)||'[]')}catch{return[]}}
function v16CancelKnownSchedules(){if(!v16Native())return;v16KnownSchedules().forEach(k=>{try{window.EconNotify.cancel(k)}catch(e){}});localStorage.setItem(V16_SCHEDULED,'[]')}
function v16SyncNativeNotifications(){v16RenderNotifyButton();if(!v16Native())return;if(!v16Enabled()||!v16HasPermission()){if(!v16Enabled())v16CancelKnownSchedules();return}const desired=new Set(),now=Date.now(),today=v16Today();v16Obligations.forEach(o=>{const preKey=`ob:${o.id}:pre`,dueKey=`ob:${o.id}:due`;if(!v16ActiveOb(o)){try{window.EconNotify.cancel(preKey);window.EconNotify.cancel(dueKey)}catch(e){}return}const rem=moneyUSD(v16RemainingUsd(o)),kind=o.kind==='receivable'?'Cobro':'Pago',preDate=v16Shift(o.due_date,-v16Num(o.alert_days)),preAt=v16ScheduleAt(preDate),dueAt=v16ScheduleAt(o.due_date),preTitle=o.kind==='receivable'?'Cobro próximo':'Pago próximo',dueTitle=o.kind==='receivable'?'Cobro vence hoy':'Pago vence hoy',body=`${o.counterparty} · ${rem} · vence ${formatDate(o.due_date)}`;if(preAt>now+60000){try{window.EconNotify.schedule(preKey,preAt,preTitle,body);desired.add(preKey)}catch(e){}}else if(o.due_date>=today&&v16DaysTo(o.due_date)<=v16Num(o.alert_days)){v16ShowOnce(`pre-now:${o.id}:${today}`,preTitle,body)}if(dueAt>now+60000){try{window.EconNotify.schedule(dueKey,dueAt,dueTitle,body);desired.add(dueKey)}catch(e){}}else if(o.due_date===today){v16ShowOnce(`due-now:${o.id}:${today}`,dueTitle,body)}else if(o.due_date<today){v16ShowOnce(`overdue:${o.id}:${today}`,kind+' vencido',`${o.counterparty} · ${rem} pendiente desde ${formatDate(o.due_date)}`)}});const old=v16KnownSchedules();old.filter(k=>!desired.has(k)).forEach(k=>{try{window.EconNotify.cancel(k)}catch(e){}});localStorage.setItem(V16_SCHEDULED,JSON.stringify(Array.from(desired)));v16Budgets.filter(b=>String(b.period_start).slice(0,7)===v16MonthKey()).forEach(b=>{const s=v16BudgetState(b),key=`budget:${b.id}:${s.over?'100':b.alert_percent}`;if(s.warn)v16ShowOnce(key,s.over?'Presupuesto excedido':'Presupuesto cerca del límite',`${v16BudgetLabel(b)} · ${s.pct.toFixed(0)}% · ${moneyUSD(s.spent)} de ${moneyUSD(s.limit)}`)});v16Goals.filter(g=>g.status==='active').forEach(g=>{const s=v16GoalState(g);if(s.achieved)v16ShowOnce(`goal:${g.id}:achieved`,'Meta financiera alcanzada',`${g.name} · ${moneyUSD(s.value)} de ${moneyUSD(s.target)}`)})}
v16Build();const v16OldCleanup=cleanupRealtime;cleanupRealtime=function(){if(v16Channel&&sb){sb.removeChannel(v16Channel);v16Channel=null}return v16OldCleanup()};const v16OldRoute=routeAfterAuth;routeAfterAuth=async function(){await v16OldRoute();if(business){v16Build();await v16Load();v16Subscribe()}};const v16OldLoadTransactions=loadTransactions;loadTransactions=async function(){const r=await v16OldLoadTransactions();if(v16Ready){v16Render();v16SyncNativeNotifications()}return r};const v16OldActivityTitle=activityTitle;activityTitle=function(a){if(a.action==='BUDGET_CREATED')return`${activityActor(a)} creó un presupuesto`;if(a.action==='BUDGET_UPDATED')return`${activityActor(a)} actualizó un presupuesto`;if(a.action==='BUDGET_DELETED')return`${activityActor(a)} eliminó un presupuesto`;if(a.action==='GOAL_CREATED')return`${activityActor(a)} creó una meta financiera`;if(a.action==='GOAL_UPDATED')return`${activityActor(a)} actualizó una meta financiera`;if(a.action==='GOAL_DELETED')return`${activityActor(a)} eliminó una meta financiera`;return v16OldActivityTitle(a)};const v16OldRenderActivity=renderActivity;renderActivity=function(){v16OldRenderActivity();const items=Array.from($('activityList')?.querySelectorAll('.activity-item')||[]);items.forEach((el,i)=>{const a=activityLogs[i],ic=el.querySelector('.activity-icon');if(!a||!ic)return;if(a.action?.startsWith('BUDGET_'))ic.textContent='📊';else if(a.action?.startsWith('GOAL_'))ic.textContent='🎯'})};$('reloadData')?.addEventListener('click',()=>setTimeout(v16Load,250));if(business){v16Load();v16Subscribe()}
})();
